const { withGradleProperties } = require("expo/config-plugins");

/** R8 does not fit in Expo's default 2048m on this app — `minifyReleaseWithR8` dies with
 *  `OutOfMemoryError: Java heap space` part-way through a release build. */
const JVM_ARGS = "-Xmx4096m -XX:MaxMetaspaceSize=512m";

/**
 * Config plugin that raises the Gradle daemon heap.
 *
 * `android/gradle.properties` is regenerated by `expo prebuild`, and
 * `expo-build-properties` exposes no option for `org.gradle.jvmargs`, so this has to be a
 * plugin rather than a checked-in file or a build-properties key.
 *
 * Replaces the existing property rather than appending, so prebuild's default does not
 * win by being read later.
 */
function withGradleMemory(config) {
  return withGradleProperties(config, (config) => {
    const properties = config.modResults.filter(
      (item) => !(item.type === "property" && item.key === "org.gradle.jvmargs")
    );
    properties.push({
      type: "property",
      key: "org.gradle.jvmargs",
      value: JVM_ARGS,
    });
    config.modResults = properties;
    return config;
  });
}

module.exports = withGradleMemory;
